struct Reflection { const char* title; const char* text; };
static const Reflection REFLECTIONS[366] = {
  {"AA Around the World", "AA may or may not get me to heaven, but it surely got me out of hell."},
  {"No Matter What", "My anger served as an iron shield, and I refused to remove it for fear God would send me still more pain."},
  {"Spiritual Awakenings", "AA is spiritual, is the eye of the hurricane, is my refuge and my comfort."},
  {"Voices of LT Sobriety", "I have always carried a meeting list and quarter for a phone call because I don't know when I am going to want another drink."},
  {"AA Around the World", "I don't need to project the future or cry about the past. Just live to the best of my ability, one day at a time."},
  {"Language of the Heart", "Excessive guilt or rebellion leads to spiritual poverty."},
  {"Beginners' Book", "When I'm in fear, my sponsor always tells me, 'Maybe you should get a bigger God.'"},
  {"Unknown", "Nothing ever falls out of the universe."},
  {"In Our Own Words", "Not drinking is the first requirement for joy; the second requirement is gratitude."},
  {"Voices of LT Sobriety", "My life and the lives of those around me do, in fact, form their own parts in a symphony of interaction."},
  {"Beginner's Book", "You've got one life to live. Don't screw it up with a lot of maybes, what-ifs, and could-have-beens. Focus on what you have."},
  {"Language of the Heart", "It is not the fault of great ideals that they are sometimes misused."},
  {"Emotional Sobriety II", "I am feeling much better now, and I thank God for AA and my good friends. I have learned how to accept their help."},
  {"Beginner's Book", "If you need a friend who understands, look no further than the rooms of AA and the Big Book. They always hold an answer and some faith for me."},
  {"Language of the Heart", "Mere change is not necessarily progress."},
  {"Beginner's Book", "I was so busy juggling the regrets of the past with the expectations of tomorrow I had no time for living in the present."},
  {"Real Recovery", "Facing ourselves ... is often more difficult than being honest with another person."},
  {"Beginner's Book", "If there are challenges to be met today, I remember other days when what seemed impossible was made possible."},
  {"AA Grapevine", "Grace is not a do-it-yourself project."},
  {"Voices of LT Sobriety", "Every recovery, though it may go unnoticed, improves the world in some way."},
  {"AA Grapevine", "Each night I pray that when the alarm clock goes off in the morning, I'll have a spiritual awakening."},
  {"Emotional Sobriety", "It doesn't do too much good to carry the Big Book on your arm all day if you don't open it up and read it."},
  {"AA Grapevine", "The temporary security of material things is a hollow shelter if built at the expense of spiritual growth."},
  {"Spiritual Awakenings II", "I have made a determined effort to focus more on seeing myself as God sees me."},
  {"No Matter What", "I don't fear for the future because I am in the loving arms of AA today."},
  {"Language of the Heart", "We found that each of us had to make willing sacrifices ... for the common welfare."},
  {"Emotional Sobriety II", "When I'm willing to pay the price for top-shelf sobriety, 'action' is still the magic word."},
  {"Emotional Sobriety II", "The great art of living is to make the best of things as they are."},
  {"Best of Bill", "As faith grows, so does inner security."},
  {"Language of the Heart", "Only mutual trust can be the foundation for great love - each of us for the other, and all of us for God."},
  {"AA Grapevine", "Few victims of this illness can expect sobriety without a major change in most aspects of living."},
  {"AA Grapevine", "If I am in pain, it may be beneficial to me if I am aware of those in even more pain ... The answer for my pain is in the Twelfth Step."},
  {"Language of the Heart", "Always a heady wine, success may sometimes cause us to forget that each of us lives on borrowed time."},
  {"Best of Grapevine", "The effort to escape from truth is the father of anxiety."},
  {"Into Action", "I don't just hear the slogans anymore; I feel them when I speak them ... They take hold of me; they change the course of my day if I let them."},
  {"Language of the Heart", "I had been living too much alone, too much aloof from my fellows, and too deaf to that voice within."},
  {"AA Grapevine", "Sobriety isn't a discrete list of tasks that you do and then check off; it's a state of being that pervades every aspect of your life."},
  {"Spiritual Awakenings II", "Am I strong enough? Am I willing to commit my life and my heart at an even deeper level to doing whatever it takes to keep moving forward?"},
  {"AA Grapevine", "The experience of reality does not have to be postponed."},
  {"Beginner's Book", "While I've never been sober today before, I count on my Higher Power to keep me sober as he has done on all those other days before."},
  {"AA Grapevine", "It doesn't matter who or what God is if I can just remember it's not me!"},
  {"Best of Grapevine", "If it were not for the 'we' of AA, there would be no 'I.'"},
  {"Language of the Heart", "There is never need to praise ourselves. We feel it better to let our friends recommend us."},
  {"Spiritual Awakenings", "Spiritual progress isn't what gets us sober, it's what keeps us sober."},
  {"Language of the Heart", "If humility can expel the obsession to drink alcohol, then surely humility can be our antidote for that subtle wine called success."},
  {"Emotional Sobriety II", "I am learning how to cope with life, people, and situations, not as I want them to be, but as they really are."},
  {"Emotional Sobriety II", "I've learned that I am not responsible for anyone's happiness except my own. Most importantly, I learned that true happiness is an inside job."},
  {"The Home Group", "Sobriety in AA is the first thing in my life that has really worked."},
  {"AA Grapevine", "The program is a road, not a resting place."},
  {"No Matter What", "A new chapter has once again started in my life - a chapter that has no ending, a chapter that I did not write, but a chapter with many characters."},
  {"Beginner's Book", "My desire to drink became a desire not to."},
  {"Unknown", "Growing pains are never to be feared, provided I am willing to learn the truth about myself from them."},
  {"AA Grapevine", "AA's greatest power is not in the program itself, but in the examples of the men [and women] who have followed it."},
  {"AA Grapevine", "The word 'alcoholic' does not turn me off anymore; in fact, it is music to my ears when it applies to me."},
  {"AA Grapevine", "Tolerance is the art of seeing yourself as others see you - and not getting mad about it."},
  {"Step By Step", "Seeing my defects is not enough to make them improve or go away - the solution seems to be following awareness with action."},
  {"Language of the Heart", "There is among us AAs the ever present need for further spiritual growth."},
  {"Into Action", "A new spiritual awakening can come at every meeting."},
  {"Spiritual Awakenings", "AA is spiritual, is the eye of the hurricane, is my refuge and my comfort."},
  {"Language of the Heart", "A religious, or spiritual experience, is the act of giving up reliance on one's own omnipotence."},
  {"AA Grapevine", "It is our experience as alcoholics that makes us of unique value ... We can approach sufferers as no one else can."},
  {"Spiritual Awakenings II", "Am I strong enough? Am I willing to commit my life and my heart at an even deeper level to doing whatever it takes to keep moving forward?"},
  {"AA Grapevine", "The more I learn the more there is to learn."},
  {"AA Grapevine", "It is when you let truth go into action, and hurl your life after your held conception of truth, that things start to happen."},
  {"Thank You for Sharing", "I believe that a man's value to himself is the sum total of his positive reaction to the little things in life."},
  {"Spiritual Awakenings", "The God I know today ... is a presence in which I find myself, just as I am."},
  {"AA Grapevine", "Sometimes I wonder if this illness isn't a gift rather than a problem."},
  {"Emotional Sobriety II", "With the help of the Fellowship, the Twelve Steps, and a Higher Power ... I do not have to be a newcomer again."},
  {"Voices of LT Sobriety", "Anonymity is a spiritual foundation not only of Tradition Twelve, but of sobriety itself."},
  {"AA Around the World", "We work; we struggle; we will survive."},
  {"AA Grapevine", "In examining the precision and aptness of the small, I can be more appreciative of the large."},
  {"The Home Group", "The power in these rooms is greater than the sum total of those of us present."},
  {"The Home Group", "By helping to insure the sobriety of others to come, we insure our own sobriety today."},
  {"AA Grapevine", "Today, as I look back over 27-plus years of sobriety, I can simply thank Him for being wherever I am going before I even get there."},
  {"Voices of LT Sobriety", "The bottle never demanded credentials or conformity - neither has AA."},
  {"AA Grapevine", "Happiness or tragedy might just depend upon a slight sign of recognition, a nod of the head or perhaps a friendly smile."},
  {"AA Grapevine", "Are you willing to be amazed?"},
  {"Spiritual Awakenings", "My Higher Power works incognito, defying definition and requiring faith."},
  {"Emotional Sobriety", "Today's sobriety cannot be chugalugged ... It has to be sipped, one taste at a time, so that each drop of serenity can be fully savored."},
  {"The Home Group", "Belonging to a group makes life an opportunity for me ... something to encourage the best in me while it helps to keep me humble about the worst in me."},
  {"AA Grapevine", "I have learned in the program not to listen to the voice of my ego when it starts whispering things."},
  {"AA Grapevine", "We have to keep looking for something better than dullness, better than average living, better than mediocre spirituality."},
  {"In Our Own Words", "I no longer pray to have my fear removed. Today, I pray that my love grows bigger than my fear and that my humility becomes greater than my shame."},
  {"Voices of LT Sobriety", "The Twelve Steps are deceptively simple but provide limitless spiritual growth for anyone with the patience to stay the course."},
  {"Spiritual Awakenings", "Until I understood and accepted my status as a human being, my effort toward seeking God was in vain."},
  {"AA Grapevine", "AA does not teach us how to handle our drinking; it teaches us how to handle our sobriety."},
  {"The Home Group", "The ability to laugh at ourselves is an intrinsic part of the healing process."},
  {"Spiritual Awakenings", "I don't believe I drank to get drunk, but always to seek in the next drink that peace for which a sick soul seems to thirst."},
  {"Voices of LT Sobriety", "Nobody argued about whose Higher Power was higher."},
  {"Beginner's Book", "Alcoholics have short memories."},
  {"AA Grapevine", "The number one way to relieve pain is to forgive."},
  {"Beginner's Book", "Be willing to be willing to follow directions and you will find your life changing in all areas."},
  {"AA Grapevine", "I need to remember how humiliated, confused, insecure and frightened I felt at my first meeting, and compare that to how I feel today."},
  {"AA Grapevine", "Life is travel - enjoy the journey, bumpy roads and all."},
  {"Language of the Heart", "All AA progress can be reckoned in terms of just two words: humility and responsibility."},
  {"Spiritual Awakenings", "Only the sharing of despair can bring us ... illumination."},
  {"AA Around the World", "I don't need to project the future or cry about the past. Just live to the best of my ability, one day at a time."},
  {"Language of the Heart", "Though my sobriety had come easy, the growing up business hadn't. Both emotional and spiritual growth have always been mighty difficult for me."},
  {"Spiritual Awakenings", "Every day, hopeless, helpless alcoholics walk into AA meetings, grab onto hope, and begin a renewal of their spirit."},
  {"Spiritual Awakenings", "There are no shibboleths in AA. We are not bound by theological doctrine ... We are many minds in our organization."},
  {"Emotional Sobriety II", "It is not stupid to accept myself and others complete with our imperfections. It would be stupid not to."},
  {"Language of the Heart", "Vision is ... the very essence of prudence."},
  {"AA Grapevine", "The whole world became mine when I had nowhere else to go."},
  {"AA Grapevine", "I build today the road I travel tomorrow."},
  {"Voices of LT Sobriety", "The spirit of AA has been with me ... for better or for worse, for richer or for poorer, in sickness and in health."},
  {"AA Grapevine", "While I have years of sobriety, I really only have this day."},
  {"Emotional Sobriety II", "Life is lived moment to moment ... and every moment provides me with an opportunity for growth."},
  {"I Am Responsible", "I ask the newcomer to help me wash the coffeepot, or put chairs away, because service was, and still is, my key to belonging."},
  {"AA Grapevine", "Don't regret growing old, it's a privilege denied to many."},
  {"Emotional Sobriety", "Success and failure share a common denominator ... both are temporary."},
  {"AA Grapevine", "The AA message does not carry itself; somebody must carry it."},
  {"Emotional Sobriety", "If you sponsor people, you'll never need a mirror."},
  {"Best of Grapevine", "God grant that AA may ever stay simple."},
  {"Voices of LT Sobriety", "I make a conscious effort to keep it simple, because the simpler I make it, the happier I become."},
  {"Best of Grapevine", "When I can identify my own shortcomings in another, the battleground between us is removed."},
  {"Language of the Heart", "There are always the constructive critics, our friends indeed. We should never fail to give them a careful hearing."},
  {"AA Grapevine", "Where before there was a gaping hole of emptiness, I seek within me that faint ember of self-love, self-worth, and desire for goodness."},
  {"Thank You for Sharing", "I heard my future told around the tables at my home group."},
  {"AA Grapevine", "I am responsible for reporting for duty and making the effort to overcome adversity, and in so doing to overcome myself."},
  {"Emotional Sobriety", "My local meetings are big on this spot-check reminder: you get what you get; it's what you do with it that counts."},
  {"AA Grapevine", "I can't walk on water, but with my Higher Power and my AA friends, I can keep my head just above it."},
  {"No Matter What", "No one at the gym, at work, in my neighborhood, or even in church had ever put their hand out to me. In AA, it happened every day."},
  {"Language of the Heart", "We have to grow or else deteriorate. For us, the 'status quo' can only be for today, never for tomorrow. Change we must; we cannot stand still."},
  {"Into Action", "First Things First. That's a real gem."},
  {"AA Around the World", "I may be a Loner but I am never alone spiritually. For this, I am deeply grateful."},
  {"No Matter What", "It's funny how life is lived forward - and understood backward."},
  {"AA Grapevine", "AA isn't for the people who need it or for the people who want it; it's for the people who are willing to do the work to get it."},
  {"Spiritual Awakenings", "What I did need and need desperately, was not more knowledge about God, but, with God's help, a deep and penetrating knowledge about myself."},
  {"Language of the Heart", "I expect to be 'on tap' but never again 'on top,' this being precisely the stance that AA hopes all its old-timers will take."},
  {"AA Around the World", "Coincidences are merely a manner in which God protects his anonymity."},
  {"Emotional Sobriety", "It's only when I stop thinking about it, stop trying to run the show, that my life may become as God intends."},
  {"Spiritual Awakenings", "Spiritual awakening ... begins with knowledge and acceptance of the truth about ourselves."},
  {"Emotional Sobriety II", "While we readily share our views, perhaps one of the nicest things about the AA program is that we don't always have to agree with each other."},
  {"AA Grapevine", "My heart sings with each new day."},
  {"Step By Step", "I have no secrets, and I fear no man. I am not anxious about death. I am alive, forever, within this 24 hours."},
  {"Into Action", "Think, think, think before you make that angry comment or mail that bitter letter. How important is it?"},
  {"Language of the Heart", "The roads to recovery are many .... AA has no monopoly on reviving alcoholics."},
  {"AA Grapevine", "I could do something about changing my own thoughts, but nothing about changing the people around me."},
  {"Best of Grapevine", "When we concentrate on loving those we think are unlovable, we find out how expansive love is."},
  {"Step By Step", "Change is scary, even if it promises a better life."},
  {"Emotional Sobriety", "A large part of my recovery has been in learning how not to listen to myself."},
  {"AA Grapevine", "I used to think that having a pint was the only way to have fun; now I know that, for me, it's the only way to destroy the fun that I'm having!"},
  {"AA Grapevine", "The Twelve Steps are not steps to take progressively in order to arrive at a conclusion, but a code for living - the constitution of a way of life."},
  {"Step By Step", "God never gives me more than I can handle, but sometimes he takes me right to the edge."},
  {"Language of the Heart", "The deception of others is nearly always rooted in the deception of ourselves."},
  {"Beginner's Book", "It's a waste of time to take God's inventory."},
  {"Emotional Sobriety II", "There has to be something to be grateful for if I am only willing to change my attitude and look for it."},
  {"In Our Own Words", "Times change, people change, and language may change. But the disease of alcoholism does not change. It always kills."},
  {"Language of the Heart", "The future belongs to you."},
  {"Best of Grapevine", "We reject fantasizing and accept reality. And we find it beautiful. For, at last, we are at peace with ourselves. And with others. And with God."},
  {"AA Grapevine", "When faith has entered the front door of our hearts, fear goes out the back."},
  {"Emotional Sobriety", "I found that the little things I took for granted on a daily basis were the things that meant the most."},
  {"Emotional Sobriety II", "I am learning how to cope with life, people, and situations, not as I want them to be, but as they really are."},
  {"AA Grapevine", "Each day I feel myself growing in recovery. I can honestly say I'm happier now than ever before in my adult life."},
  {"Young & Sober", "I am glad for everything that has happened to me. I have found a way of life that I wouldn't trade for anything in the world."},
  {"Into Action", "To be teachable, I had to be reachable."},
  {"Voices of LT Sobriety", "I learned that if I had the capacity to be honest, I would get better."},
  {"AA Grapevine", "Some days are harder than others, but I have been told a person is not measured by what she has achieved but by what she has overcome."},
  {"Spiritual Awakenings", "One of the truly great gifts in this Fellowship of mutually concerned people is the gift of the art of listening."},
  {"Emotional Sobriety", "I still don't know much about heaven, but I've learned some valuable lessons about life on earth."},
  {"AA Grapevine", "It took two years to learn that I wasn't getting anywhere because I was always in such a hurry."},
  {"In Our Own Words", "God has given me this day to use as I wish; Alcoholics Anonymous shows me how to live it without a drink."},
  {"Emotional Sobriety", "What I've had to figure out is that I can't figure anything out."},
  {"Emotional Sobriety", "The simplicity of this program never changes - what works is constant: trust in God, clean house, and work with others."},
  {"Step By Step", "Only a gift given in love and gratitude is blessed to the giver and precious to the receiver."},
  {"In Our Own Words", "Spirituality is not based on logic, it is faith-driven. Faith makes the impossible possible."},
  {"In Our Own Words", "My past sobriety is not a ticket to future sobriety. I have to pay that fare and make the decision to recover daily."},
  {"Language of the Heart", "In the nick of time, and by God's grace, each of us has been enabled to develop a growing sense of the meaning and purpose of his own life."},
  {"AA Grapevine", "Our mistakes of yesterday can be stepping stones for tomorrow if we do something about them today."},
  {"Language of the Heart", "\"In our Twelve Traditions we have set our faces against nearly every trend in the outside world."},
  {"No Matter What", "One day leads to the next, no matter how unhappy I choose to be."},
  {"Language of the Heart", "Good public relations are AA lifelines reaching out to the alcoholic who still does not know us."},
  {"Voices of LT Sobriety", "My energy is now my own. I don't have to spend it on being angry and negative ... There's no longer that terrible rush to judgment"},
  {"AA Grapevine", "Some days I feel almost normal, almost sane."},
  {"Beginner's Book", "Not picking up a drink creates infinite possibilities for me ... Who knows? This could be the greatest day of my life."},
  {"Beginner's Book", "I borrowed others' faith for a long time, and now I'm beginning to get a bit of my own."},
  {"Voices of LT Sobriety", "Everyone around me said, 'Quit drinking,' but no one was able to tell me how."},
  {"Spiritual Awakenings II", "When I effectively practice my program, I am only a cheap dime-store garden hose carrying God's message of hope, recovery, and forgiveness."},
  {"AA Grapevine", "In AA, we discover that it is impossible to give without receiving, or receive without giving."},
  {"Emotional Sobriety", "In the first six months of my own sobriety, I worked hard with many alcoholics. Not a one responded. Yet this work kept me sober."},
  {"Emotional Sobriety II", "When I'm willing to pay the price for top-shelf sobriety, 'action' is still the magic word."},
  {"Language of the Heart", "Our Serenity Prayer ... brings a new light to us that can dissipate our old-time and nearly fatal habit of fooling ourselves."},
  {"No Matter What", "I don't fear for the future because I am in the loving arms of AA today."},
  {"AA Grapevine", "The only way I ever found to displace a thought was to put another thought in its stead."},
  {"Step By Step", "If we fail to 'repair,' we can only impair."},
  {"Emotional Sobriety", "I don't foresee outgrowing my need for help."},
  {"AA Grapevine", "There has to be something to be grateful for if I am only willing to change my attitude and look for it."},
  {"Spiritual Awakenings", "We sense that here in AA this shared darkness has become a shared light."},
  {"Spiritual Awakenings", "AA is spiritual, is the eye of the hurricane, is my refuge and my comfort ... Thanks to AA for making a place for broken hearts and wounded souls."},
  {"AA Grapevine", "Humility is not thinking less of yourself, but thinking of yourself less."},
  {"Beginner's Book", "What matters is what works, not my opinion of what works."},
  {"Language of the Heart", "We cannot grow very much unless we constantly try to envision what the eternal spiritual values are."},
  {"Emotional Sobriety", "I have never mastered the art of self-sponsorship, and I doubt that I ever will."},
  {"The Home Group", "When we reach a maximum in understanding, we know how very much we shall never understand."},
  {"Language of the Heart", "I have a feeling that if I ever find myself in Heaven, it will be from backing away from Hell."},
  {"AA Grapevine", "They say love heals all, and I am confident the future is bright."},
  {"Beginner's Book", "The smile from my face traveled to my heart."},
  {"AA Grapevine", "Humility is the soil in which all other virtues grow."},
  {"I Am Responsible", "We can't grow without giving ourselves space for silence and the voice within."},
  {"Emotional Sobriety", "The things that count cease being those that can be held in the hand and become only what can be held in the heart."},
  {"AA Grapevine", "You never know until you go out to meet it what any given day is going to be, but the way you go to meet it surely makes a difference."},
  {"AA Grapevine", "I am grateful to AA that I have learned some humility, so when offered help, I can now say, 'Yes, I can use your assistance.'"},
  {"Step By Step", "The word powerless ... described my situation with alcohol perfectly and completely. My life was more than unmanageable, it was illegal."},
  {"Language of the Heart", "The temporary or seeming good can often be the deadly enemy of the permanent best."},
  {"I Am Responsible", "Recovery is giving it away. If you don't give it away you can't have it ... Be part of the pipeline."},
  {"AA Grapevine", "I'm better able to love people when the storm of my judgmental mind settles, when I understand and empathize rather than criticize and condemn."},
  {"Step By Step", "Clearly, the chief mark of restoration to sanity is our not taking the first drink."},
  {"Beginner's Book", "It feels good to be trusted."},
  {"Voices of LT Sobriety", "Times change, alcoholism doesn't."},
  {"Beginner's Book", "AA gives us a Ph.D. in life and a black belt in common sense."},
  {"Emotional Sobriety II", "The inner energy that is love connects all the parts of us - our emotional, mental, physical, and spiritual selves."},
  {"Step by Step", "The simple word 'we' stands at the entrance to the Steps, reminding me that my power is limited."},
  {"Best of Grapevine", "Imperfection offers me the freedom of a million potentials.\""},
  {"Spiritual Awakenings", "I sabotage myself if I attach my sobriety to people, places, or things."},
  {"Best of Grapevine", "I am responsible for reporting for duty and making the effort to overcome the adversity, and in so doing to overcome myself."},
  {"AA Around the World", "I was told when I got sober that I could act my way into right thinking, but I could never think my way into right action."},
  {"In Our Own Words", "'How will I know if I've really hit my bottom?' I asked at my home group. 'When you stop digging,' they told me."},
  {"AA Grapevine", "Now that my spiritual eyes have begun to open, the world is much fuller."},
  {"Emotional Sobriety", "There are winners and whiners, and sometimes I seem to embody both. I am, as my friends remind me, a human being."},
  {"AA Grapevine", "I can't imagine anything that would make me so mad, glad, or sad that I would want to go back to what I was before AA."},
  {"No Matter What", "In this moment, regardless of what happened before or what may happen tomorrow, what is the very best thing I can possibly do, right now?"},
  {"In Our Own Words", "I no longer pray to have my fear removed. Today, I pray that my love grows bigger than my fear and that my humility becomes greater than my shame."},
  {"Emotional Sobriety II", "There has to be something to be grateful for if I am only willing to change my attitude and look for it."},
  {"No Matter What", "We can always come up with a reason to drink. The secret is, how many reasons can we come up with to stay sober?"},
  {"A.A. in Prison", "The most difficult thing a man can do is turn his eyes inward upon his real self."},
  {"A.A. in Prison", "Tomorrow - and all the tomorrows to come - are but extensions of right here, right now."},
  {"Language of the Heart", "Those little maxims 'Easy Does It' and 'Live and Let Live' have come to be deeply meaningful and significant."},
  {"AA Grapevine", "You cannot get ahead until you learn to be here."},
  {"Language of the Heart", "We AAs shall have to hang together - or else hang separately!"},
  {"Voices of LT Sobriety", "Thanks to my God, AA, and the Twelve Steps, sobriety has become the 'easier, softer way' for me."},
  {"Best of Grapevine", "We will still have daydreams ... But they will be constructive dreams, rather than mere flights of fancy."},
  {"Beginner's Book", "My emotional bottom came in sobriety ... I actually had to sit and feel all those feelings I had worked so hard to drown out with alcohol."},
  {"One on One", "Empathy, not sympathy or pity, is the most useful quality a sponsor can cultivate."},
  {"Language of the Heart", "The alcoholic is in no greater peril than when he takes his sobriety for granted."},
  {"Voices of LT Sobriety", "Sober now, there was this tug at my heart, the love of one alcoholic for another."},
  {"AA Grapevine", "Spiritual growth and experiences are not limited to orthodox believers in a deity, any more than the disease of alcoholism is limited to skid-row bums."},
  {"Spiritual Awakenings", "Some of us take a long time to 'come to' before we can 'come to believe' that there is any hope for us."},
  {"One on One", "Spiritual fitness is required if I am to be of service to anyone."},
  {"Spiritual Awakenings II", "I have made a determined effort to focus more on seeing myself as God sees me."},
  {"Beginners' Book", "Nothing improves if you drink."},
  {"Language of the Heart", "As a fellowship we ask nothing of wealth or power."},
  {"AA Grapevine", "AA works on all kinds of nuts (including myself). I just needed to find the right wrench."},
  {"Language of the Heart", "Truly transforming spiritual experiences are nearly always founded on calamity and collapse."},
  {"The Home Group", "If you want to be happy, go to a meeting. If you want to be twice as happy, go to two meetings."},
  {"Language of the Heart", "The temptations of riches could sometimes be worse than the pains of poverty."},
  {"Language of the Heart", "Each of us must conform reasonably well to AA's Steps and Traditions, or else we shall go mad or die of alcoholism."},
  {"AA Grapevine", "Forgiveness seems to depend more on the love of the one who does the forgiving than on the lovability of the one being forgiven."},
  {"Emotional Sobriety", "At some point in each today, we recovering alcoholics need to pay ourselves a friendly visit."},
  {"Language of the Heart", "Sobriety - freedom from alcohol - through the teaching and practice of the Twelve Steps, is the sole purpose of an AA group."},
  {"AA Grapevine", "Before we can be of any use to anybody else, we must find the beginnings of the answer for ourselves."},
  {"Step By Step", "Sobriety does interesting things to the mind - clears it up some, lets a bit of honesty and truth filter in, and begins to demand reality."},
  {"Spiritual Awakenings II", "There are AA emotions and attitudes that transcend language."},
  {"AA Grapevine", "We are called to unity, not uniformity."},
  {"Language of the Heart", "The temporary or seeming good can often be the deadly enemy of the permanent best."},
  {"AA Grapevine", "Learning is the very essence of humility. The two walk hand in hand. Humility, as I see it, grows out of an urge to learn from everyone and everything."},
  {"Language of the Heart", "Let us AAs no longer be takers from society. Instead, let us be givers."},
  {"AA Grapevine", "It is impossible to know everyone, but if I try to relate myself with just one other person, something will happen, something remarkable."},
  {"AA Grapevine", "The more I change, the more I hope the Traditions and principles of AA don't change."},
  {"AA Grapevine", "The leap of faith must be taken again and again over greater and greater distances."},
  {"AA Grapevine", "Whatever strengthens the spirituality of the group strengthens my spirituality, and vice versa."},
  {"Language of the Heart", "May we never forget that we live by the grace of God - on borrowed time."},
  {"Thank You for Sharing", "Few of us will ever be famous, but we can all be great because we serve each other."},
  {"AA Grapevine", "I remember asking my sponsor, 'When do I start the Steps?' He replied, 'When do you want to get well?'"},
  {"Emotional Sobriety", "Success and failure share a common denominator ... Both are temporary."},
  {"Language of the Heart", "Those little maxims 'Easy Does It' and 'Live and Let Live' have come to be deeply meaningful and significant."},
  {"AA Grapevine", "I can recall that even as a small child I had allergic reactions to certain forms of reality."},
  {"AA Grapevine", "My spiritual awakening has involved three major leaps: Save Me, Help Me, and Use Me."},
  {"Language of the Heart", "Always a heady wine, success may sometimes cause us to forget that each of us lives on borrowed time."},
  {"In Our Own Words", "Alcohol robbed me of my adolescence. But I've learned to grow up in AA."},
  {"Emotional Sobriety", "What counts is not that which can be held in the hand but that which can be held in the heart."},
  {"Spiritual Awakenings II", "Alcoholics Anonymous has given me something of real value that I can share with others."},
  {"AA Grapevine", "If I try to soar with the eagles, I'm likely to appear more of a turkey."},
  {"Real Recovery", "I cannot adequately describe how light I feel since I took the Fifth Step, and how soundly I sleep."},
  {"AA Grapevine", "AA is not an 'insiders' kind of Fellowship, thanks to the efforts of hundreds of thousands of AAs worldwide. We'll help any drunk anywhere, any time."},
  {"AA Grapevine", "Habits are like cork or lead - they tend to keep you up or hold you down."},
  {"Voices of LT Sobriety", "The AA message is a message from one amateur to another."},
  {"AA Grapevine", "Hope is tremendous progress for someone who once was 'hopeless.'"},
  {"AA Grapevine", "As AA grows, it is impossible to know everyone, but if I try to relate myself with just one other person, something will happen, something remarkable."},
  {"Best of Bill", "Just how and when we tell the truth - or keep silent - can often reveal the difference between genuine integrity and none at all."},
  {"Language of the Heart", "Faith is more than our greatest gift; its sharing with others is our greatest responsibility."},
  {"AA Grapevine", "Today's disappointment, viewed six months hence, may turn out to be one of the best breaks we ever got."},
  {"Unknown", "I no longer feel isolated, alone or without purpose. I feel like life is going somewhere, and I don't feel like I have to know where."},
  {"WillingAA Grapevine", "Those of us who saw the shadow of the butterfly net overhead are blessed if we get to know that an open mind can save."},
  {"AA Around the World", "Until today, at least, I am getting further away from that first drink, which is the one that inevitably leads me to complete disaster."},
  {"Beginner's Book", "AA has taught me that I'm the architect of my own success or happiness. The quality of my sobriety is up to me - it will be what I want it to be."},
  {"Spiritual Awakenings", "My Higher Power works incognito, defying definition and requiring faith."},
  {"Spiritual Awakenings", "Ever fresh in my heart is a song of thanksgiving for my expanding sobriety, as the opening door to timeless truth."},
  {"Emotional Sobriety II", "The inner energy that is love connects all the parts of us - our emotional, mental, physical, and spiritual selves."},
  {"Emotional Sobriety II", "Every day, every meeting, there's something more to learn."},
  {"Emotional Sobriety II", "While we readily share our views, perhaps one of the nicest things about the AA program is that we don't always have to agree with each other."},
  {"No Matter What", "I've never taken my sobriety for granted because I know I'm only one drink away from ruining my life."},
  {"Best of Grapevine", "Certainly, we need leaders, but we must regard them as the human agent of the Higher Power and not with undue adulation as individuals."},
  {"Spiritual Awakenings", "I seek strength not to be superior to my brothers, but to be able to fight my greatest enemy - myself."},
  {"One on One", "Without a connection to my Higher Power, I am the same old person with the same old defects, causing the same old pain in my life and others'."},
  {"AA Grapevine", "Are you finally ready to let go and live your destiny?"},
  {"Language of the Heart", "My stability came out of trying to give, not out of demanding that I receive."},
  {"AA Grapevine", "Great love is the sunlight of AA's tree of life."},
  {"One on One", "No self-pity, no anger, no jealousy, no hate. What had this program done to me?"},
  {"One On One", "I did not know what real happiness was when I came through the doors of AA. I needed someone to teach me."},
  {"The Home Group", "Why dwell on what you can't do? ... Why not concentrate on what you can do and do it?"},
  {"Voices of LT Sobriety", "I think my Higher Power stepped in and started leading me out of the alcoholic life, as I seemed incapable of doing it on my own."},
  {"Emotional Sobriety", "The first thing my sponsor told me was, 'I don't have time to help you stay sick ... but if you want to get better I'd be glad to help."},
  {"AA Grapevine", "Through our failures and trials we get the opportunity to soundly test our merits and virtues."},
  {"Voices of LT Sobriety", "AA is a caring community ... of people who understand how others can be trapped in deep loneliness and despair."},
  {"Spiritual Awakenings II", "Alcoholics Anonymous has given me something of real value that I can share with others."},
  {"AA Grapevine", "In AA we aim not only for sobriety - we try again to become citizens of the world that we rejected, and of the world that once rejected us."},
  {"Best of Grapevine", "The amount of reality I turn my back on is the amount I lose."},
  {"AA Grapevine", "Today, the two most important things in recovery for me are willingness and action ... Today, I have a smile that I can offer other alcoholics."},
  {"Beginner's Book", "Turn toward that power and ask for help whenever you feel disturbed or afraid, the way a plant turns toward the light."},
  {"AA Grapevine", "Everyone's recipe for serenity is different. It's like vegetable soup - nobody makes it quite the same."},
  {"Language of the Heart", "\"This issue of the Grapevine marks the anniversary of its founding exactly fifteen [now seventy] years ago."},
  {"No Matter What", "At the end of each day ... I hope that I can say a short prayer of gratitude for another day of sobriety. Anything else good that happens is a bonus."},
  {"AA Grapevine", "I pray for the willingness to listen carefully to everyone I encounter, for some may have the words I need to hear."},
  {"Best of Grapevine", "Truth is to inner space what sunshine is to a garden."},
  {"Emotional Sobriety II", "With the help of the Fellowship, the Twelve Steps, and a Higher Power ... I do not have to be a newcomer again."},
  {"No Matter What", "With the clock ticking like it is, I do not have time for anger, resentment, or self-pity. Time is far too precious."},
  {"AA Grapevine", "Sponsorship is a bridge to trusting the human race, the very race we once resigned from. In learning to trust, we are strengthening our sobriety."},
  {"Best of Grapevine", "When I step out under the stars at night, they no longer seem cold or far away. They are a part of me and I am a part of them."},
  {"AA Grapevine", "The most important thing AA has given me is the chance to get to know someone I never knew - myself."},
  {"Best of Grapevine", "Forgiveness entered my life through my heart, not my head."},
  {"AA Grapevine", "I like to say that AA is a program you can use to learn to follow the will of your higher self."},
  {"AA Grapevine", "Serenity is not the absence of conflict, but the ability to cope with it."},
  {"AA Grapevine", "Experience is what you get when you don't get what you want."},
  {"Spiritual Awakenings II", "Admitting I lack faith does me no harm ... being different, dissenting from views by a majority of my peers, is not a source of guilt."},
  {"AA Grapevine", "When it seems like love just isn't enough, I remind myself that it is all I have to give beyond my experience, strength and hope."},
  {"Best of Grapevine", "In AA, we slowly learn to stop stewing in our own juice and to start loving other people."},
  {"Best of Grapevine", "Experience has taught us that simplicity is basic in preservation of our personal sobriety and helping those in need."},
  {"In Our Own Words", "We AAs are the best listeners in the world - that is, when we're not talking!"},
  {"AA Grapevine", "There is no you or me or them. Everything is connected and the salvation of each of us is linked to the salvation of all of us."},
  {"The Home Group", "The place to start in achieving an informed group conscience is with myself."},
  {"AA Grapevine", "I am thankful to God for all that I have, and for all that I don't have."},
  {"AA Grapevine", "I don't know when it happened, but one day I felt like I belonged in my group of sober guys ... I didn't have to leave."},
  {"Step By Step", "Through Step Five, God has removed my shame about being an alcoholic."},
  {"AA Grapevine", "Today, my short version of the Third Step is this: Keep taking care of me, Lord, because I appreciate it now."},
  {"No Matter What", "I made the decision to turn my will and my life over to the care of God, and then I got out of the way."},
  {"Spiritual Awakenings", "The Steps will speak to my condition wherever I am in sobriety."},
  {"AA Grapevine", "If faith without works is dead, willingness without action is fantasy."},
  {"Language of the Heart", "If humility can expel the obsession to drink alcohol, then surely humility can be our antidote for that subtle wine called success."},
  {"AA Grapevine", "I need to constantly inch forward in AA, closer to the center, to avoid being thrown from the spinning wheel that is my life."},
  {"Language of the Heart", "Let us always love the best in others, and never fear their worst."},
  {"No Matter What", "Regardless of what happened before or what may happen tomorrow, what is the very best thing I can possibly do, right now?"},
  {"AA Grapevine", "Work on Step Nine has freed me from fears about the past and given me more energy to devote to present-day living - this twenty-four hours."},
  {"Voices of LT Sobriety", "I was relieved to learn that I didn't have to believe, only be willing to believe. This I could do."},
  {"Best of Bill", "Had I not been blessed with wise and loving advisers, I might have cracked up long ago."},
  {"AA Grapevine", "Asking for help is not just a path to humility; it is a path to connection with my fellows and with God."},
  {"Spiritual Awakenings", "Service made me feel useful. Twelfth Step work taught me to accept my past."},
  {"AA Grapevine", "I no longer always have to be right."},
  {"Best of Grapevine", "Human beings come and go, but principles go on and on."},
  {"Voices of LT Sobriety", "I continue to attend AA meetings because anything I know about recovery seems to have a shelf-life of 72 hours."},
  {"In Our Own Words", "I believe anyone can be helped if they have an honest desire to stop drinking. I'm living proof."},
  {"AA Grapevine", "Surrender has nothing to do with giving up. It means to stop fighting."},
  {"Best of Grapevine", "Trying to figure it all out in my head brings on waves of fear, anxiety, and self-reproach. So I say, 'What can I do for myself and others today?'"},
  {"AA Grapevine", "As I trudge the Road of Happy Destiny, AA holds my left hand, God holds my right, and I have no hands left to pick up a drink."},
  {"One On One", "Sponsorship is a bridge to trusting the human race, the very race we once resigned from. In learning to trust, we are strengthening our sobriety."},
  {"AA Grapevine", "We have grown from two people to two million ... We must be doing something right."},
  {"AA Grapevine", "The rewards of asking for help - increased humility, connection, and trust - are well worth the effort."},
  {"Language of the Heart", "In the life of each AA member, there still lurks a tyrant. His name is alcohol."},
  {"Beginners' Book", "I try to accept reality instead of trying to control it. When I make that adjustment, the struggle ends."},
  {"AA Grapevine", "Good things increase in direct proportion to my willingness to become teachable."},
  {"Voices of LT Sobriety", "I make a conscious effort to keep it simple, because the simpler I make it, the happier I become."},
  {"Voices of LT Sobriety", "I asked, 'Is this AA?' One man said, 'Yes, but we ain't got no women.' I said, 'You do now,' and sat down on the couch in the front of the room."},
  {"Emotional Sobriety II", "I am feeling much better now, and I thank God for AA and my good friends. I have learned how to accept their help."},
  {"Emotional Sobriety II", "Sobriety is a constant process of uncovering, discovering, and discarding."},
  {"AA Grapevine", "Until I was at my complete bottom, alcohol wasn't even my problem. But thankfully, when I did hit bottom, AA was not hard to find."},
  {"Emotional Sobriety", "My sponsor ... gave me some good advice. 'Take the words success and failure out of your vocabulary. Replace them with honesty and effort.'"},
  {"Spiritual Awakenings", "Nothing improves if you drink."},
};
static const uint16_t REFLECTION_COUNT = 366;
